import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int y;
        int capacity;
        int flow;
        int cost;

        public Edge() {}

        public Edge(int y, int capacity, int flow, int cost) {
            this.y = y;
            this.capacity = capacity;
            this.flow = flow;
            this.cost = cost;
        }
    }

    static final long INF64 = 1000000000000000000L;
    static final int MAXN = 1000007;
    static List<Integer>[] g = new ArrayList[MAXN];
    static List<Edge> edgesArr = new ArrayList<>();
    static long totalCost = 0;
    static long[] distArr = new long[MAXN];
    static int[] predArr = new int[MAXN];
    static int[] peArr = new int[MAXN];
    static int[] inq = new int[MAXN];

    static int s = MAXN - 2;
    static int t = MAXN - 1;

    static int mod_value(int a) {
        int MOD = 1000000007;
        return ((a % MOD) + MOD) % MOD;
    }

    static int calc(int a, int b) {
        int MOD = 1000000007;
        return (int)((a * (long)b) % MOD);
    }

    static int fast_pow(int a, int k) {
        int res = 1;
        while (k > 0) {
            if ((k & 1) != 0) {
                res = calc(res, a);
            }
            a = calc(a, a);
            k >>= 1;
        }
        return res;
    }

    static int get_inv(int a) {
        int b = fast_pow(a, 1000000005);
        // assert calc(a, b) == 1;
        return b;
    }

    static int residualCap(int x) {
        Edge e = edgesArr.get(x);
        return e.capacity - e.flow;
    }

    static void updateFlow() {
        Arrays.fill(distArr, INF64);
        Arrays.fill(predArr, -1);
        Arrays.fill(peArr, -1);
        Arrays.fill(inq, 0);
        distArr[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.add(s);
        inq[s] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            inq[u] = 0;
            for (int eIdx : g[u]) {
                if (residualCap(eIdx) == 0) continue;
                Edge e = edgesArr.get(eIdx);
                int y = e.y;
                long cst = e.cost;
                if (distArr[y] > distArr[u] + cst) {
                    distArr[y] = distArr[u] + cst;
                    predArr[y] = u;
                    peArr[y] = eIdx;
                    if (inq[y] == 0) {
                        inq[y] = 1;
                        q.add(y);
                    }
                }
            }
        }
        int cur = t;
        while (cur != s) {
            int eIdx = peArr[cur];
            edgesArr.get(eIdx).flow++;
            edgesArr.get(eIdx ^ 1).flow--;
            cur = predArr[cur];
        }
        totalCost += distArr[t];
    }

    static void addEdgeToGraph(int x, int y, int cap, int cst) {
        g[x].add(edgesArr.size());
        edgesArr.add(new Edge(y, cap, 0, cst));
        g[y].add(edgesArr.size());
        edgesArr.add(new Edge(x, 0, 0, -cst));
    }

    static int n, m, k, c, d;

    static void readInputData() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        c = sc.nextInt();
        d = sc.nextInt();

        for (int i = 0; i < MAXN; i++) {
            g[i] = new ArrayList<>();
        }

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt();
            x--;
            addEdgeToGraph(s, x, 1, 0);
        }

        int layersCount = 101;
        for (int i = 0; i < layersCount; i++) {
            addEdgeToGraph(i * n, t, k, i * c);
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt() - 1;
            int y = sc.nextInt() - 1;
            for (int t_layer = 0; t_layer < layersCount - 1; t_layer++) {
                for (int j = 0; j < k; j++) {
                    addEdgeToGraph(x + t_layer * n, y + t_layer * n + n, 1, d * (j * 2 + 1));
                }
            }
            for (int t_layer = 0; t_layer < layersCount - 1; t_layer++) {
                for (int j = 0; j < k; j++) {
                    addEdgeToGraph(y + t_layer * n, x + t_layer * n + n, 1, d * (j * 2 + 1));
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < layersCount - 1; j++) {
                addEdgeToGraph(i + j * n, i + j * n + n, k, 0);
            }
        }

        for (int i = 0; i < k; i++) {
            updateFlow();
        }

        System.out.println(totalCost);
        sc.close();
    }

    public static void main(String[] args) {
        readInputData();
    }
}
